CREATE TABLE IF NOT EXISTS "work_hub_tasks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id") ON DELETE CASCADE, "title" text NOT NULL, "description" text, "status" text NOT NULL DEFAULT 'open', "priority" text NOT NULL DEFAULT 'normal', "assignee_user_id" integer REFERENCES "users"("id"), "created_by_id" integer NOT NULL REFERENCES "users"("id"), "due_at" timestamptz, "recurrence" jsonb, "version" integer NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "work_hub_tasks_assignee_idx" ON "work_hub_tasks" ("assignee_user_id", "status", "due_at");
CREATE INDEX IF NOT EXISTS "work_hub_tasks_owner_idx" ON "work_hub_tasks" ("owner_org_type", "owner_org_id", "updated_at");
CREATE TABLE IF NOT EXISTS "work_hub_task_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "task_id" uuid NOT NULL REFERENCES "work_hub_tasks"("id") ON DELETE CASCADE, "actor_user_id" integer REFERENCES "users"("id"), "event_type" text NOT NULL, "detail" jsonb, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_checklist_templates" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "name" text NOT NULL, "current_version" integer NOT NULL DEFAULT 1, "definition" jsonb NOT NULL, "created_by_id" integer NOT NULL REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_checklist_instances" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "template_id" uuid NOT NULL REFERENCES "work_hub_checklist_templates"("id"), "template_version" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id"), "assignee_user_id" integer REFERENCES "users"("id"), "snapshot" jsonb NOT NULL, "responses" jsonb NOT NULL DEFAULT '{}'::jsonb, "due_at" timestamptz, "status" text NOT NULL DEFAULT 'open', "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_form_templates" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "name" text NOT NULL, "current_version" integer NOT NULL DEFAULT 1, "definition" jsonb NOT NULL, "recurrence" jsonb, "created_by_id" integer NOT NULL REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_form_instances" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "template_id" uuid NOT NULL REFERENCES "work_hub_form_templates"("id"), "template_version" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id"), "assignee_user_id" integer REFERENCES "users"("id"), "definition_snapshot" jsonb NOT NULL, "due_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_form_submissions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "instance_id" uuid NOT NULL REFERENCES "work_hub_form_instances"("id"), "prior_submission_id" uuid, "version" integer NOT NULL, "submitted_by_id" integer NOT NULL REFERENCES "users"("id"), "values" jsonb NOT NULL, "submitted_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_form_submission_version_unique" ON "work_hub_form_submissions" ("instance_id", "version");
CREATE TABLE IF NOT EXISTS "work_hub_acknowledgements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "subject_type" text NOT NULL, "subject_id" text NOT NULL, "subject_version" integer NOT NULL, "user_id" integer NOT NULL REFERENCES "users"("id"), "acknowledgement_text" text, "acknowledged_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_acknowledgements_unique" ON "work_hub_acknowledgements" ("subject_type", "subject_id", "subject_version", "user_id");
CREATE TABLE IF NOT EXISTS "work_hub_approval_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id"), "subject_type" text NOT NULL, "subject_id" text NOT NULL, "subject_version" integer NOT NULL, "mode" text NOT NULL DEFAULT 'ordered', "status" text NOT NULL DEFAULT 'pending', "requested_by_id" integer NOT NULL REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_approval_steps" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "request_id" uuid NOT NULL REFERENCES "work_hub_approval_requests"("id") ON DELETE CASCADE, "step_order" integer NOT NULL, "approver_user_id" integer NOT NULL REFERENCES "users"("id"), "decision" text, "comment" text, "decided_at" timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_approval_step_unique" ON "work_hub_approval_steps" ("request_id", "step_order", "approver_user_id");
CREATE TABLE IF NOT EXISTS "work_hub_announcements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id"), "title" text NOT NULL, "body" text NOT NULL, "urgency" text NOT NULL DEFAULT 'normal', "acknowledgement_required" boolean NOT NULL DEFAULT false, "version" integer NOT NULL DEFAULT 1, "published_by_id" integer NOT NULL REFERENCES "users"("id"), "published_at" timestamptz NOT NULL DEFAULT now(), "expires_at" timestamptz, "withdrawn_at" timestamptz);
CREATE TABLE IF NOT EXISTS "work_hub_announcement_recipients" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "announcement_id" uuid NOT NULL REFERENCES "work_hub_announcements"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id"), "viewed_at" timestamptz, "acknowledged_at" timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_announcement_recipient_unique" ON "work_hub_announcement_recipients" ("announcement_id", "user_id");
CREATE TABLE IF NOT EXISTS "work_hub_availability" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "user_id" integer NOT NULL REFERENCES "users"("id"), "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "available" boolean NOT NULL DEFAULT true, "recurrence" jsonb, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "work_hub_availability_user_time_idx" ON "work_hub_availability" ("user_id", "starts_at", "ends_at");
CREATE TABLE IF NOT EXISTS "work_hub_shifts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id"), "title" text NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "timezone" text NOT NULL, "open" boolean NOT NULL DEFAULT false, "qualification_codes" text[], "recurrence" jsonb, "version" integer NOT NULL DEFAULT 1, "created_by_id" integer NOT NULL REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "work_hub_shifts_owner_time_idx" ON "work_hub_shifts" ("owner_org_type", "owner_org_id", "starts_at");
CREATE TABLE IF NOT EXISTS "work_hub_shift_assignments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shift_id" uuid NOT NULL REFERENCES "work_hub_shifts"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id"), "status" text NOT NULL DEFAULT 'assigned', "warning_snapshot" jsonb, "assigned_by_id" integer REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_shift_assignment_unique" ON "work_hub_shift_assignments" ("shift_id", "user_id");
CREATE TABLE IF NOT EXISTS "work_hub_shift_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shift_id" uuid NOT NULL REFERENCES "work_hub_shifts"("id") ON DELETE CASCADE, "request_type" text NOT NULL, "requested_by_id" integer NOT NULL REFERENCES "users"("id"), "target_user_id" integer REFERENCES "users"("id"), "status" text NOT NULL DEFAULT 'pending', "warning_snapshot" jsonb, "decided_by_id" integer REFERENCES "users"("id"), "decided_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_meetings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "channel_id" uuid REFERENCES "work_hub_channels"("id"), "title" text NOT NULL, "agenda" text, "timezone" text NOT NULL, "recurrence" jsonb, "recording_allowed" boolean NOT NULL DEFAULT false, "policy_version" integer NOT NULL DEFAULT 1, "created_by_id" integer NOT NULL REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_meeting_occurrences" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "meeting_id" uuid NOT NULL REFERENCES "work_hub_meetings"("id") ON DELETE CASCADE, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz, "status" text NOT NULL DEFAULT 'scheduled', "provider_room_id" text, "recording_state" text NOT NULL DEFAULT 'off', "transcript_state" text NOT NULL DEFAULT 'off', "created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_meeting_occurrence_unique" ON "work_hub_meeting_occurrences" ("meeting_id", "starts_at");
CREATE TABLE IF NOT EXISTS "work_hub_meeting_participants" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id"), "role" text NOT NULL DEFAULT 'participant', "rsvp" text NOT NULL DEFAULT 'pending', "hand_raised_at" timestamptz, "muted" boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_meeting_participant_unique" ON "work_hub_meeting_participants" ("occurrence_id", "user_id");
CREATE TABLE IF NOT EXISTS "work_hub_meeting_attendance" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id"), "joined_at" timestamptz NOT NULL DEFAULT now(), "left_at" timestamptz);
CREATE INDEX IF NOT EXISTS "work_hub_meeting_attendance_idx" ON "work_hub_meeting_attendance" ("occurrence_id", "user_id", "joined_at");
CREATE TABLE IF NOT EXISTS "work_hub_meeting_chat" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id"), "body" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_meeting_artifacts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "artifact_type" text NOT NULL, "storage_key" text, "provider_artifact_id" text, "state" text NOT NULL DEFAULT 'pending', "metadata" jsonb, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "work_hub_transcript_segments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "artifact_id" uuid NOT NULL REFERENCES "work_hub_meeting_artifacts"("id") ON DELETE CASCADE, "speaker_user_id" integer REFERENCES "users"("id"), "starts_at_ms" integer NOT NULL, "ends_at_ms" integer NOT NULL, "text" text NOT NULL, "confidence" real);
CREATE INDEX IF NOT EXISTS "work_hub_transcript_playback_idx" ON "work_hub_transcript_segments" ("artifact_id", "starts_at_ms");
CREATE TABLE IF NOT EXISTS "work_hub_meeting_consents" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id"), "policy_version" integer NOT NULL, "response" text NOT NULL, "responded_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_meeting_consent_unique" ON "work_hub_meeting_consents" ("occurrence_id", "user_id", "policy_version");
CREATE TABLE IF NOT EXISTS "work_hub_calendar_connections" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "provider" text NOT NULL, "capabilities" text[] NOT NULL, "encrypted_credentials" text NOT NULL, "status" text NOT NULL DEFAULT 'connected', "created_by_id" integer NOT NULL REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), "revoked_at" timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_calendar_connection_unique" ON "work_hub_calendar_connections" ("owner_org_type", "owner_org_id", "provider");
CREATE TABLE IF NOT EXISTS "work_hub_external_calendars" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "connection_id" uuid NOT NULL REFERENCES "work_hub_calendar_connections"("id") ON DELETE CASCADE, "external_id" text NOT NULL, "name" text NOT NULL, "selected" text NOT NULL DEFAULT 'false');
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_external_calendar_unique" ON "work_hub_external_calendars" ("connection_id", "external_id");
CREATE TABLE IF NOT EXISTS "work_hub_external_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "calendar_id" uuid NOT NULL REFERENCES "work_hub_external_calendars"("id") ON DELETE CASCADE, "external_id" text NOT NULL, "title" text NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "location" text, "organizer" text, "attendee_display" jsonb, "update_marker" text, "cancelled_at" timestamptz, "synced_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_external_event_unique" ON "work_hub_external_events" ("calendar_id", "external_id");
CREATE INDEX IF NOT EXISTS "work_hub_external_event_time_idx" ON "work_hub_external_events" ("starts_at", "ends_at");
CREATE TABLE IF NOT EXISTS "work_hub_sync_cursors" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "connection_id" uuid NOT NULL REFERENCES "work_hub_calendar_connections"("id") ON DELETE CASCADE, "resource_type" text NOT NULL, "cursor" text, "last_success_at" timestamptz, "last_error_code" text, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_sync_cursor_unique" ON "work_hub_sync_cursors" ("connection_id", "resource_type");
CREATE TABLE IF NOT EXISTS "work_hub_search_documents" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "context_kind" text NOT NULL, "context_id" text NOT NULL, "subject_type" text NOT NULL, "subject_id" text NOT NULL, "visibility_revision" text NOT NULL, "title" text, "searchable_text" text NOT NULL, "metadata" jsonb, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_search_document_unique" ON "work_hub_search_documents" ("subject_type", "subject_id");
CREATE INDEX IF NOT EXISTS "work_hub_search_owner_idx" ON "work_hub_search_documents" ("owner_org_type", "owner_org_id", "updated_at");
